                    "sql": "CREATE or replace TABLE onyc-wh.maplemonk.shipment_status_mapping ( SHIPPING_STATUS string(16777216), Mapped_Status string(16777216) ); Insert INTO onyc-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists onyc-wh.maplemonk.facility_pincode( facility string, pincode string ); create or replace table onyc-wh.maplemonk.category_mapping ( category string, final_category string ); INSERT INTO onyc-wh.maplemonk.category_mapping (category, final_category) values (\'OST\', \'OST\'), (\'OVERSIZED T-SHIRT\', \'OST\'), (\'JGR\', \'JGR\'), (\'JOGGERS\', \'JGR\'), (\'PNT\', \'PNT\'), (\'PANTS\', \'PNT\'), (\'HST\', \'HST\'), (\'HALF SLEEVE T-SHIRT\', \'HST\'), (\'SHR\', \'SHR\'), (\'SHIRT\', \'SHR\'), (\'HOD\', \'HOD\'), (\'HOODIE\', \'HOD\'), (\'SWT\', \'SWT\'), (\'SWEATSHIRT\', \'SWT\'), (\'COMBO\', \'COMBO\'), (\'COMBOS\', \'COMBO\'), (\'CTP\', \'CTP\'), (\'CROP TOP\', \'CTP\'), (\'TANK TOP\', \'TANK TOP\'), (\'PULLOVER\', \'PULLOVER\'), (\'CO-ORD\', \'CO-ORD\'), (\'VST\', \'VST\'), (\'VEST\', \'VST\'), (\'JKT\', \'JKT\'), (\'JACKET\', \'JKT\'), (\'SRT\', \'SRT\'), (\'SHORTS\', \'SRT\'), (\'FULL SLEEVE T-SHIRT\', \'FULL SLEEVE T-SHIRT\'), (\'GIFT CARDS\', \'GIFT CARDS\'), (\'TRY\', \'TRY\'), (\'T-SHIRT\', \'TRY\'), (\'BDN\', \'BDN\'), (\'BODYCON\', \'BDN\'), (\'TANK BODYCON\', \'TANK BODYCON\'), (\'BXR\', \'BXR\'), (\'BOXER\', \'BXR\'), (\'RNS\', \'RNS\'), (\'RIBBED TOPS\', \'RNS\'), (\'NA\', \'NA\'); CREATE OR REPLACE TABLE onyc-wh.maplemonk.marketplace_mapping ( marketplace STRING, final_marketplace STRING ); INSERT INTO onyc-wh.maplemonk.marketplace_mapping (marketplace, final_marketplace) VALUES (\'FLIPKART\', \'Flipkart\'), (\'LIMEROAD\', \'Limeroad\'), (\'MYNTRAPPMP\', \'Myntra\'), (\'PERSONAL\', \'Personal\'), (\'SHOPIFY\', \'Website\'), (\'AMAZON\', \'Amazon\'), (\'POPCLUB\', \'Popclub\'), (\'NYKAA FASHION\', \'Nykaa Fashion\'), (\'NYKAA_FASHION\', \'Nykaa Fashion\'), (\'CUSTOM\', \'Custom\'), (\'AJIO_OMNI\', \'Ajio\'), (\'NYKAA_COM\', \'Nykaa.com\'), (\'STUMBL\', \'Stumbl\'), (\'BEWAKOOF\', \'Bewakoof\'), (\'FLIPKART\', \'Flipkart\'), (\'OFFLINE\', \'Offline\'), (\'AMAZON.IN\', \'Amazon\'), (\'WEBSITE\',\'Website\'); create or replace table onyc-wh.maplemonk.onyc_wh_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(coalesce(b.FINAL_UTM_CHANNEL,GA4.CHANNEL)) AS CHANNEL ,Upper(coalesce(b.source_name,b.FINAL_UTM_SOURCE,GA4.final_source)) AS SOURCE ,b.ORDER_ID ,b.order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(c.shipping_last_update_date as timestamp), cast(b.shipping_status_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(coalesce(c.order_Status, b.ORDER_STATUS)) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(c.shipping_status, b.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,c.shipping_status, b.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,c.shipping_status, b.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and coalesce(lower(c.order_status), lower(b.order_status)) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 then ifnull(quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and coalesce(lower(c.order_status), lower(b.order_status)) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 then ifnull(total_sales,0) end returned_sales ,case when coalesce(lower(c.order_status), lower(b.order_status)) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,CAST(CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, c.shipping_status, b.shipping_status, d.shipping_status))IN (\'delivered\',\'delivered to origin\') THEN DATE_DIFF(DATE(COALESCE(CAST(c.shipping_last_update_date AS TIMESTAMP), CAST(b.shipping_status_update_date AS TIMESTAMP), CAST(d.shipping_last_update_date AS TIMESTAMP))), DATE(b.ORDER_TIMESTAMP), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, c.shipping_status, b.shipping_status, d.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CURRENT_DATE(), DATE(b.ORDER_TIMESTAMP), DAY)END AS INT64) AS Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.PRODUCT_CATEGORY)) PRODUCT_CATEGORY ,upper(b.size) size ,coalesce(b.sku_code,b.commonsku) commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,b.discount_codes ,b.color ,b.mrp ,b.cogs ,b.sku_tax_rate ,b.product_image_url ,b.product_type ,upper(coalesce(r.return_reason,er.return_reason)) return_reason ,r.return_request_number ,coalesce(date(r.return_requested_at),date(er.return_initiated_date)) as return_requested_at ,r.return_approved_at ,coalesce(date(r.return_date),date(er.return_date)) as return_date ,coalesce(r.return_request_type,er.return_type) as return_type ,coalesce(r.returned_quantity,er.returned_quantity) as total_returned_quantity ,coalesce(r.refunded_amount,er.total_credit_note_amount) as total_return_amount from onyc-wh.maplemonk.onyc_wh_SHOPIFY_FACT_ITEMS b left join ( select transactionid, final_source, channel from maplemonk.onyc_wh_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(b.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join ( select order_name, return_line_item_id, max(return_reason) return_reason, max(return_request_number) as return_request_number, max(return_requested_at) as return_requested_at, max(return_approved_at) as return_approved_at, max(return_date) as return_date, max(return_request_type) as return_request_type, sum(ifnull(returned_quantity,0)) as returned_quantity, sum(ifnull(refunded_amount,0)) as refunded_amount from maplemonk.onyc_RETURNSPRIME_CONSOLIDATED group by 1,2 qualify row_number() over (partition by order_name,return_line_item_id order by return_requested_at desc) =1 ) r on replace(b.order_name,\'#\',\'\') = replace(r.order_name, \'#\',\'\') and lower(b.LINE_ITEM_ID) = lower(r.return_line_item_id) left join ( select reference_code, saleorderitemcode, max(case when upper(seller_return_reason) like any (\'%rto%\',\'%return to origin%\',\'%cancelled%\') then \'RTO\' else \'Customer Return\' end) as return_type, max(upper(coalesce(channel_return_reason,seller_return_reason))) return_reason, max(return_initiated_date) return_initiated_date, max(return_date) return_date, sum(ifnull(returned_quantity,0)) returned_quantity, sum(ifnull(total_credit_note_amount,0)) as total_credit_note_amount from maplemonk.onyc_wh_easyecom_returns_fact_items where lower(marketplace) like \'%shopify%\' group by 1,2 qualify row_number() over (partition by reference_code,saleorderitemcode order by return_initiated_date desc) =1 ) er on replace(b.order_name,\'#\',\'\') = replace(er.reference_code, \'#\',\'\') and lower(b.LINE_ITEM_ID) = lower(er.saleorderitemcode) left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from onyc-wh.maplemonk.onyc_wh_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from onyc-wh.maplemonk.onyc_wh_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(c.Marketplace_LineItem_ID, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from onyc-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from onyc-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) LEFT JOIN onyc-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.product_category) UNION ALL SELECT cast(NULL AS string) customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, \'AMAZON\' AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS timestamp), CAST(UFI.shipping_last_update_date AS timestamp) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(afi.tax, 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, COALESCE(EEFI.awb, UFI.awb) AS AWB, NULL AS Payment_Gateway, UPPER(COALESCE(EEFI.payment_mode, UFI.payment_mode)) AS Payment_Mode, UPPER(COALESCE(EEFI.Courier, UFI.courier)) AS COURIER, COALESCE(EEFI.manifest_date, UFI.dispatch_date) AS DISPATCH_DATE, COALESCE(EEFI.delivered_date , UFI.delivered_date ) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status, EEFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS INT64) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(DATE(COALESCE(EEFI.delivered_date , UFI.delivered_date)), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID, EEFI.SKU) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(coalesce(cm.final_Category,AFI.PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, UPPER(AFI.size) AS size ,CAST(AFI.commonsku AS STRING) AS commonsku ,UPPER(coalesce(EEFI.warehouse_name, UFI.warehouse_name)) AS WAREHOUSE, COALESCE(AFI.pincode, UFI.pincode, EEFI.pincode) AS pincode, coalesce(EEFI.pickup_pincode, fa.pincode) source_pincode ,null as discount_codes ,afi.color ,afi.mrp ,afi.cogs ,afi.sku_tax_rate ,afi.product_image_url ,afi.product_type ,upper(er.return_reason) return_reason ,null as return_request_number ,date(er.return_initiated_date) as return_requested_at ,null as return_approved_at ,date(er.return_date) as return_date ,er.return_type as return_type ,er.returned_quantity as total_returned_quantity ,er.total_credit_note_amount as total_return_amount FROM onyc-wh.maplemonk.onyc_wh_AMAZON_FACT_ITEMS AFI left join ( select reference_code, replace(sku,\'`\',\'\') as sku, max(case when upper(seller_return_reason) like any (\'%rto%\',\'%return to origin%\',\'%cancelled%\') then \'RTO\' else \'Customer Return\' end) as return_type, max(upper(coalesce(channel_return_reason,seller_return_reason))) return_reason, max(return_initiated_date) return_initiated_date, max(return_date) return_date, sum(ifnull(returned_quantity,0)) returned_quantity, sum(ifnull(total_credit_note_amount,0)) as total_credit_note_amount from maplemonk.onyc_wh_easyecom_returns_fact_items where lower(marketplace) like \'%amazon%\' group by 1,2 qualify row_number() over (partition by reference_code,replace(sku,\'`\',\'\') order by return_initiated_date desc) =1 ) er on AFI.Order_id = er.reference_code AND AFI.commonSKU = er.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM onyc-wh.maplemonk.onyc_wh_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) EEFI ON AFI.Order_id = EEFI.reference_code AND AFI.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM onyc-wh.maplemonk.onyc_wh_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(AFI.order_id as string) = cast(UFI.order_id as string) AND cast(AFI.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from onyc-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM onyc-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) LEFT JOIN onyc-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(afi.product_category) UNION ALL SELECT NULL AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,b.reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.mapped_category)) AS PRODUCT_CATEGORY ,null AS size ,b.commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,null as discount_codes ,b.color ,b.mrp ,b.cogs ,b.sku_tax_rate ,b.product_image_url ,b.product_type ,upper(er.return_reason) return_reason ,null as return_request_number ,date(er.return_initiated_date) as return_requested_at ,null as return_approved_at ,date(er.return_date) as return_date ,er.return_type as return_type ,er.returned_quantity as total_returned_quantity ,er.total_credit_note_amount as total_return_amount FROM onyc-wh.maplemonk.onyc_wh_EasyEcom_FACT_ITEMS b left join ( select reference_code, saleorderitemcode, max(case when upper(seller_return_reason) like any (\'%rto%\',\'%return to origin%\',\'%cancelled%\') then \'RTO\' else \'Customer Return\' end) as return_type, max(upper(coalesce(channel_return_reason,seller_return_reason))) return_reason, max(return_initiated_date) return_initiated_date, max(return_date) return_date, sum(ifnull(returned_quantity,0)) returned_quantity, sum(ifnull(total_credit_note_amount,0)) as total_credit_note_amount from maplemonk.onyc_wh_easyecom_returns_fact_items group by 1,2 qualify row_number() over (partition by reference_code,saleorderitemcode order by return_initiated_date desc) =1 ) er on b.reference_code = er.reference_code AND b.Marketplace_LineItem_ID = er.saleorderitemcode LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM onyc-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN onyc-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.mapped_category) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\', \'%flipkart%\')) and b.reference_code not in (select distinct reference_code from onyc-wh.maplemonk.onyc_wh_unicommerce_fact_items) UNION ALL select cast(NULL AS string) customer_id, upper(fi.Shop_name) AS Shop_name, \'FLIPKART\' AS marketplace, \'FLIPKART\' AS CHANNEL, \'FLIPKART\' AS SOURCE, fi.ORDER_ID, fi.ORDER_ID AS reference_code, NULL AS PHONE, fi.NAME, COALESCE(UFI.EMAIL, fi.EMAIL) AS EMAIL, CAST(UFI.shipping_last_update_date AS timestamp) AS SHIPPING_LAST_UPDATE_DATE, fi.SKU, cast(fi.PRODUCT_ID as string) PRODUCT_ID, fi.PRODUCT_NAME, cast(null as string) as CURRENCY, NULL AS CITY, fi.State AS State, UPPER(fi.order_item_status) AS Order_Status, CAST(fi.ORDER_date AS DATE) AS Order_Date, CAST(fi.ORDER_date AS datetime) Order_Time, fi.QUANTITY, (fi.line_item_sales - fi.tax) as GROSS_SALES_BEFORE_TAX, fi.DISCOUNT AS DISCOUNT, fi.TAX, fi.SHIPPING_PRICE, line_item_sales AS SELLING_PRICE, UPPER(UFI.order_status) AS OMS_order_status, UPPER(UFI.shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, line_item_id AS SALEORDERITEMCODE, line_item_id AS SALES_ORDER_ITEM_ID, UFI.awb AS AWB, NULL AS Payment_Gateway, UPPER(coalesce(fi.payment_mode,UFI.payment_mode)) AS Payment_Mode, UPPER(coalesce(fi.courier,UFI.courier)) AS COURIER, coalesce(cast(fi.dispatch_date as datetime),cast(UFI.dispatch_date as datetime)) AS DISPATCH_DATE, coalesce(fi.delivery_date,UFI.delivered_date) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, fi.IS_REFUND AS RETURN_FLAG, CASE WHEN fi.is_refund = 1 THEN CAST(fi.quantity AS INT64) END AS returned_quantity, CASE WHEN fi.is_refund = 1 THEN fi.line_item_sales END AS returned_sales, CASE WHEN fi.is_refund = 0 AND LOWER(fi.order_item_status) = \'cancelled\' THEN CAST(fi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status,eeFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(fi.ORDER_date AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, eeFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(fi.ORDER_date AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_D, UPPER(eeFI.commonsku) AS SKU_CODE, fi.product_name_final AS PRODUCT_NAME_FINAL, upper(fi.product_category) as PRODUCT_CATEGORY, fi.size AS size, fi.commonsku as commonsku, UPPER(coalesce(fi.warehouse_id,eeFI.warehouse_name)) AS WAREHOUSE, COALESCE(fi.pincode, eeFI.pincode) AS pincode, NULL AS pickup_pincode, cast(null as string) as discount_codes, fi.color, fi.mrp, fi.cogs, fi.sku_tax_rate, fi.product_image_url, fi.product_type ,upper(coalesce(fi.return_reason,fi.return_sub_reason,er.return_reason)) return_reason ,fi.return_id as return_request_number ,coalesce(date(er.return_initiated_date),date(fi.return_approval_date)) as return_requested_at ,datetime(fi.return_approval_date) as return_approved_at ,date(er.return_date) as return_date ,er.return_type as return_type ,coalesce((case when fi.is_refund =1 then fi.quantity end),er.returned_quantity) as total_returned_quantity ,coalesce((case when fi.is_refund =1 then fi.total_sales end),er.total_credit_note_amount) as total_return_amount from maplemonk.onyc_flipkart_fact_items fi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM Maplemonk.onyc_wh_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%flipkart%\' ) EEFI ON fi.Order_id = EEFI.reference_code AND fi.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM MAPLEMONK.onyc_wh_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%flipkart%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(fi.order_id as string) = cast(UFI.order_id as string) AND cast(fi.product_id as string) = cast(UFI.PRODUCT_ID as string) left join ( select reference_code, saleorderitemcode, max(case when upper(seller_return_reason) like any (\'%rto%\',\'%return to origin%\',\'%cancelled%\') then \'RTO\' else \'Customer Return\' end) as return_type, max(replace(upper(coalesce(channel_return_reason,seller_return_reason)),\'_\',\' \')) return_reason, max(return_initiated_date) return_initiated_date, max(return_date) return_date, sum(ifnull(returned_quantity,0)) returned_quantity, sum(ifnull(total_credit_note_amount,0)) as total_credit_note_amount from maplemonk.onyc_wh_easyecom_returns_fact_items where lower(marketplace) like \'%flipkart%\' group by 1,2 qualify row_number() over (partition by reference_code,saleorderitemcode order by return_initiated_date desc) =1 ) er on fi.order_id = er.reference_code AND fi.line_item_id = er.saleorderitemcode left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from Maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM Maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, fi.ORDER_item_STATUS)) = LOWER(ShipMap.shipping_status) ; CREATE OR REPLACE TABLE onyc-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE onyc-wh.maplemonk.onyc_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, Case When lower(o.payment_mode) like \'online\' or lower(o.payment_mode) like \'prepaid\' then \'PREPAID\' else o.payment_mode end as Payment_mode_group, o.* FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM onyc-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM onyc-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN onyc-wh.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE onyc-wh.maplemonk.onyc_wh_sales_consolidated DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE onyc-wh.maplemonk.onyc_wh_sales_consolidated ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, channel, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE onyc-wh.maplemonk.onyc_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRA PRADESH.\', \'ANDHRAPRADESH\', \'AÃ±DHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KALRNATAKA\', \'KARANATAKA\', \'KARNATAKA\', \'UTTARA KANNADA, KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\', \'KANNUR, KERALA\', \'KOTTAYAM, KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'M.P.\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASHTA\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARSHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NA\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'BODAPADA BODAPADA NAYAGARH, ODISHA 752070 INDIA PH\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\', \'PUNAJB\', \'PANJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\', \'TELANAGANA\', \'TELEGANA\', \'TELENGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTAR PARDESH\', \'UTTARPRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'DISTRICT-DARJEELING, WEST BENGAL\', \'WEST BANGAL\', \'WESTBENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\' , \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI & DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NCT-DELHI\', \'NEW DELHI\', \'SOUTH WEST DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\', \'JAMMU&KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'ANDHRA PRADESH\', \'ANDHRA PRADESH.\', \'ANDHRAPRADESH\', \'AÃ±DHRA PRADESH\', \'AR\', \'ARUNACHAL PRADESH\', \'AS\', \'ASSAM\', \'BR\', \'BIHAR\', \'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'GA\', \'GOA\', \'GJ\', \'GUJARAT\', \'GUJARAT\', \'GUJRAT\', \'HR\', \'HARYANA\', \'HP\', \'HIMACHAL PRADESH\', \'JH\', \'JHARKHAND\', \'KA\', \'KARNATAKA\', \'KALRNATAKA\', \'KARANATAKA\', \'KARNATAKA\', \'UTTARA KANNADA, KARNATAKA\', \'KL\', \'KERALA\', \'KANNUR, KERALA\', \'KOTTAYAM, KERALA\', \'MP\', \'MADHYA PRADESH\', \'M.P.\', \'MH\', \'MAHARASHTRA\', \'MAHARASHTA\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARSHTRA\', \'MN\', \'MANIPUR\', \'ML\', \'MEGHALAYA\', \'MZ\', \'MIZORAM\', \'NL\', \'NA\', \'NAGALAND\', \'OR\', \'ODISHA\', \'BODAPADA BODAPADA NAYAGARH, ODISHA 752070 INDIA PH\', \'ORISSA\', \'PB\', \'PUNJAB\', \'PUNAJB\', \'PANJAB\', \'RJ\', \'RAJASTHAN\', \'SK\', \'SIKKIM\', \'TN\', \'TAMIL NADU\', \'TAMILNADU\', \'TS\', \'TL\', \'TELANGANA\', \'TELANAGANA\', \'TELEGANA\', \'TELENGANA\', \'TR\', \'TRIPURA\', \'UP\', \'UTTAR PRADESH\', \'UTTAR PARDESH\', \'UTTARPRADESH\', \'UTTER PRADESH\', \'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\', \'WB\', \'WEST BENGAL\', \'DISTRICT-DARJEELING, WEST BENGAL\', \'WEST BANGAL\', \'WESTBENGAL\', \'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\', \'CH\', \'CHANDIGARH\', \'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\' , \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI & DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'LD\', \'LAKSHADWEEP\', \'DL\', \'DELHI\', \'NCT-DELHI\', \'NEW DELHI\', \'SOUTH WEST DELHI\', \'PY\', \'PUDUCHERRY\', \'PONDICHERRY\', \'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\', \'JAMMU&KASHMIR\', \'LADAKH\' ); CREATE OR REPLACE TABLE onyc-wh.maplemonk.onyc_wh_returns_consolidated AS select CAST(fi.return_approved_at AS DATETIME) AS RETURN_DATE, UPPER(sc.CHANNEL) AS Marketing_channel, UPPER(sc.marketplace) as marketplace, case when fi.return_request_type = \'return\' then \'CUSTOMER RETURN\' when fi.return_request_type = \'exchange\' then \'CUSTOMER EXCHANGE\' END AS RETURN_TYPE, SUM(fi.returned_quantity) AS TOTAL_RETURNED_QUANTITY, SUM(ifnull(coalesce(fi.refunded_amount,Ur.TOTAL_RETURN_AMOUNT),0)) AS TOTAL_RETURN_AMOUNT, SUM(ifnull(coalesce(fi.total_tax,ur.RETURN_TAX),0)) AS TOTAL_RETURN_TAX, coalesce((SUM(ifnull(fi.refunded_amount,0)) - sum(ifnull(fi.total_tax,0))),sum(ifnull(ur.RETURN_AMOUNT_WITHOUT_TAX,0))) AS TOTAL_RETURN_AMOUNT_EXCL_TAX from onyc-wh.maplemonk.onyc_RETURNSPRIME_CONSOLIDATED fi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER( PARTITION BY reference_code,saleorderitemcode)rw FROM onyc-wh.maplemonk.onyc_wh_sales_consolidated ) WHERE rw=1 )sc ON fi.order_name = sc.reference_code AND fi.order_item_id = sc.saleorderitemcode LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER( PARTITION BY reference_code,sale_order_item_code)rw FROM onyc-wh.Maplemonk.onyc_wh_unicommerce_returns_fact_items where lower(marketplace) like \'%shopify%\' ) WHERE rw=1 ) ur ON fi.order_name = ur.reference_code AND fi.order_item_id = split(ur.sale_order_item_code,\'-\')[offset(0)] group by 1,2,3,4 UNION ALL SELECT CAST(er.Return_Date AS DATE) AS return_Date, upper(er.Marketing_channel) as Marketing_channel, UPPER(er.marketplace) AS Marketplace, UPPER(er.return_type) AS RETURN_TYPE, SUM(CAST(er.Returned_quantity AS INT64)) AS TOTAL_RETURNED_QUANTITY, SUM(CAST(er.Total_Credit_Note_Amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT, cast(\'0\' as int64) as Total_return_tax, SUM(CAST(er.Total_Credit_Note_Amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM maplemonk.onyc_wh_easyecom_returns_fact_items er WHERE UPPER(er.marketplace) NOT LIKE \'%AMAZON%\' AND UPPER(er.marketplace) NOT LIKE \'%B2B%\' GROUP BY CAST(er.Return_Date AS DATE), UPPER(er.marketplace), upper(er.Marketing_channel), UPPER(er.return_type) UNION ALL SELECT cast(RETURN_COMPLETE_DATE as datetime) AS RETURN_DATE, UPPER(Marketing_CHANNEL) AS Marketing_channel, UPPER(fr.MARKETPLACE) AS Marketplace, RETURN_TYPE, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM onyc-wh.Maplemonk.onyc_wh_unicommerce_returns_fact_items fr LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from onyc-wh.Maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fr.marketplace) = lower(mm.marketplace) WHERE NOT(lower(FR.marketplace) like \'%shopify%\') GROUP BY 1,2,3,4 ;",
                    "transaction": true
